raiz = Path.cwd()
assert (raiz / "manage.py").exists(), "rode na raiz do projeto (pasta vigidesastres)"
for nome, (aceitos, depois) in TROCAS.items():
    atual = (raiz / nome).read_text(encoding="utf-8").replace("\r\n", "\n")
    if atual != depois and atual not in aceitos:
        raise SystemExit(f"{nome} tem alterações que eu não conheço; nada foi gravado. Me mande o git diff dele.")
for nome, (aceitos, depois) in TROCAS.items():
    (raiz / nome).write_text(depois, encoding="utf-8", newline="\n")
for nome, texto in NOVOS.items():
    (raiz / nome).parent.mkdir(parents=True, exist_ok=True)
    (raiz / nome).write_text(texto, encoding="utf-8", newline="\n")
print("ok. Agora: python -m pytest -q, python -m etl previsao, python manage.py gerar_alertas e python manage.py runserver")
